cat > /app/tests/unit/conftest.py << 'EOF'
import pytest
import sys

# Check if habitat_sim is available
try:
    import habitat_sim
    HABITAT_SIM_AVAILABLE = True
except ImportError:
    HABITAT_SIM_AVAILABLE = False

def pytest_collection_modifyitems(config, items):
    """Skip tests that require habitat_sim if it's not available."""
    if HABITAT_SIM_AVAILABLE:
        return

    skip_habitat = pytest.mark.skip(reason="habitat_sim not available on this platform")
    for item in items:
        # Check if the test module imports habitat_sim
        if "habitat_sim" in item.fspath.strpath:
            item.add_marker(skip_habitat)
EOF

